mapper.select:
SELECT

FROM logs l
LEFT JOIN app_registrations ar ON ar.id = l.app_id


        AND ar.code = #{criteria.appCode}


        AND l.trace_id = #{criteria.traceId}


        AND l.log_kind = #{criteria.kind}


        AND l.level IN

            #{lvl}



        AND l.server_ts >= #{criteria.from}


        AND l.server_ts < #{criteria.to}


        AND l.message LIKE CONCAT(#{criteria.keyword}, '%')


        AND l.request_id = #{criteria.requestId}


        AND (l.server_ts < #{cursorTs}
             OR (l.server_ts = #{cursorTs} AND l.id < #{cursorId}))


ORDER BY l.server_ts DESC, l.id DESC
LIMIT #{limit}

SELECT

FROM logs l
LEFT JOIN app_registrations ar ON ar.id = l.app_id
WHERE l.trace_id = #{traceId}
ORDER BY l.server_ts ASC, l.id ASC
LIMIT #{limit}
